type KaraokeCaptionsElementProps = Omit<
  ComponentProps<typeof KaraokeCaptionsScene>,
  | "from"
  | "durationInFrames"
  | "trimBefore"
  | "playbackRate"
  | "loop"
  | "freeze"
  | "hidden"
  | "name"
  | "showInTimeline"
  | "cropLeft"
  | "cropRight"
  | "cropTop"
  | "cropBottom"
  | "premountFor"
  | "postmountFor"
  | "styleWhilePremounted"
  | "styleWhilePostmounted"
  | "controls"
> & {
  readonly style?: CSSProperties;
};

/** What a prop falls back to when Studio does not pass it, reset included. */
const KaraokeCaptionsDefaults = {
  text: "Acme reconciles every transaction automatically",
  emphasize: "automatically",
  preset: "karaoke",
  accentColor: "#FFE81F",
  fontSize: 45,
  fontWeight: 0,
  aspect: "landscape",
  emphasisScale: 1.08,
  speed: 1,
} satisfies Partial<KaraokeCaptionsElementProps>;

/** The Inspector's controls. Timing, transform, crop and premount come with `wrapInSequence`. */
const KaraokeCaptionsSchema = {
  text: {
    type: "text-content",
    default: "Acme reconciles every transaction automatically",
    description: "Line text",
  },
  emphasize: {
    type: "text-content",
    default: "automatically",
    description: "Emphasized words (comma-separated)",
  },
  accentColor: {
    type: "color",
    default: "#FFE81F",
    description: "Accent",
    keyframable: false,
  },
  fontSize: {
    type: "number",
    default: 45,
    min: 0,
    max: 96,
    step: 1,
    description: "Font size",
    hiddenFromList: false,
    keyframable: false,
  },
  emphasisScale: {
    type: "number",
    default: 1.08,
    min: 1,
    max: 1.2,
    step: 0.01,
    description: "Emphasis scale",
    hiddenFromList: false,
    keyframable: false,
  },
  fontFamily: { type: "font-family", default: undefined, description: "Font" },
  speed: {
    type: "number",
    default: 1,
    min: 1,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
    keyframable: false,
  },
} as const satisfies InteractivitySchema;

/**
 * In over the first frames, out over the last. Opacity only: nothing moves, so
 * no glyph can snap to the pixel grid on the way out.
 */
function KaraokeCaptionsFade({ children }: { children: ReactNode }) {
  const frame = useCurrentFrame();
  const enter = Math.min(1, (frame + 1) / 6);
  const leave = 1;
  return (
    <AbsoluteFill showInTimeline={false} style={{ opacity: enter * leave }}>
      {children}
    </AbsoluteFill>
  );
}

const KaraokeCaptionsInner = forwardRef<
  HTMLDivElement,
  KaraokeCaptionsElementProps
>(({ style, ...props }, ref) => {
  // The layer's length, from the Sequence `wrapInSequence` puts around this.
  const { durationInFrames } = useVideoConfig();
  const rest = { ...KaraokeCaptionsDefaults, ...props };
  // The scene measures its copy once, on mount. An Inspector edit changes the
  // props without remounting it, so the key does.
  const key = JSON.stringify(props, (k, v) =>
    k === "children" ? undefined : v,
  );

  // width/height are what useVideoConfig() reports inside this Sequence, so
  // the scene lays itself out in its stage rather than the whole composition.
  // It is not a layer of its own: the one Studio shows is the wrapper's.
  return (
    <Sequence
      layout="none"
      showInTimeline={false}
      durationInFrames={durationInFrames}
      width={1280}
      height={320}
    >
      <div
        ref={ref}
        style={{
          position: "relative",
          width: 1280,
          height: 160,
          color: "black",
          fontFamily: "initial",
          fontSize: 16,
          fontStyle: "normal",
          fontVariant: "normal",
          fontWeight: 400,
          fontStretch: "normal",
          fontKerning: "auto",
          fontFeatureSettings: "normal",
          fontVariationSettings: "normal",
          lineHeight: "normal",
          letterSpacing: "normal",
          wordSpacing: "normal",
          textAlign: "start",
          textIndent: 0,
          textTransform: "none",
          textShadow: "none",
          textRendering: "auto",
          whiteSpace: "normal",
          wordBreak: "normal",
          overflowWrap: "normal",
          hyphens: "manual",
          direction: "ltr",
          visibility: "visible",
          ...style,
        }}
      >
        <div
          style={{
            position: "absolute",
            left: 0,
            top: -80,
            width: 1280,
            height: 320,
          }}
        >
          <KaraokeCaptionsFade>
            <KaraokeCaptionsScene key={key} {...rest} />
          </KaraokeCaptionsFade>
        </div>
      </div>
    </Sequence>
  );
});

export const KaraokeCaptions = Interactive.withSchema({
  Component: KaraokeCaptionsInner,
  componentName: "<KaraokeCaptions>",
  schema: KaraokeCaptionsSchema,
  wrapInSequence: true,
});
